pub fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    // Loop invariants we maintain:
    // - 0 <= i <= n
    // - result.len() == i
    // - all elements in result are 1
    for i in 0..n {
        debug_assert!(i <= n);
        debug_assert!(result.len() == i);
        debug_assert!(result.iter().all(|&x| x == 1));

        result.push(1);

        // After push:
        debug_assert!(result.len() == i + 1);
        debug_assert!(result.iter().all(|&x| x == 1));

        // Termination measure: remaining = n - (i + 1), decreases each iteration.
        debug_assert!(n >= i + 1);
    }

    debug_assert!(result.len() == n);
    debug_assert!(result.iter().all(|&x| x == 1));
    result
}